class BasicTokeniser {
    constructor(doLowerCase, tokeniseChinese, replaceAccents) {
        this.doLowerCase = doLowerCase;
        this.tokeniseChinese = tokeniseChinese;
        this.replaceAccents = replaceAccents;
    }

    /**
     * Checks space separator (Zs), line separator (Zl), or paragraph separator (Zp),
     * Common control character (\t, \n, \r, etc.),
     * whitespace-like characters (NBSP, Figure Space, Narrow No-Break Space).
     * isWhiteSpace("")
     * Refer:
     *   1) https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Regular_expressions/Unicode_character_class_escape
     *   2) https://unicode.org/reports/tr44/#White_Space
     *
     * @param character Character to validate
     * @returns {boolean} Is whitespace or not
     * @since 0.1.0
     */
    isWhiteSpace(character) {
        return /\p{White_Space}|\p{Space_Separator}/u.test(character)
    }

    /**
     * Checks the character is control character or not
     *
     * @param character character Character to validate
     * @returns {boolean} Is control character or not
     * @since 0.1.0
     */
    isNotControlCharacter(character) {
        return (character !== '\t' && character !== '\n' && character !== '\r') // No I18N
            && /\P{C}/u.test(character);
    }

    /**
     * Checks the character is chinese character or not
     *
     * @param character Character to validate
     * @returns {boolean} Is Chinese character or not
     * @since 0.1.0
     */
    isChineseCharacter(character) {
        // Checks whether character is the codepoint of a CJK character
        // This defines a "Chinese character" as anything in the CJK Unicode block.
        // character = character.charCodeAt(0);

        // CJK Compatibility Ideographs Supplement
        return (character >= 0x4E00 && character <= 0x9FFF)
            || // CJK Unified Ideographs
            (character >= 0x3400 && character <= 0x4DBF)
            || // CJK Unified Ideographs Extension A
            (character >= 0x20000 && character <= 0x2A6DF)
            || // CJK Unified Ideographs Extension B
            (character >= 0x2A700 && character <= 0x2B73F)
            || // CJK Unified Ideographs Extension C
            (character >= 0x2B740 && character <= 0x2B81F)
            || // CJK Unified Ideographs Extension D
            (character >= 0x2B820 && character <= 0x2CEAF)
            || // CJK Unified Ideographs Extension E
            (character >= 0xF900 && character <= 0xFAFF)
            || // CJK Compatibility Ideographs
            (character >= 0x2F800 && character <= 0x2FA1F);
    }

    /**
     * Checks the character is Punctuation or not
     *
     * @param character Character to validate
     * @return Is Punctuation or not
     * @since 1.1.0
     */
    isPunctuation(character) {
        let charCode = character.codePointAt(0)
        // Check ASCII punctuation ranges
        if ((charCode >= 33 && charCode <= 47)
            || (charCode >= 58 && charCode <= 64)
            || (charCode >= 91 && charCode <= 96)
            || (charCode >= 123 && charCode <= 126)) {
            return true;
        }

        // Check the character type is other than ASCII punctuation?
        return /\p{P}/u.test(character);
    }


    Tokenise(text) {
        let builder = this.cleanText(text);
        if (this.tokeniseChinese) {
            builder = this.tokeniseChineseChars(builder);
        }

        if (this.replaceAccents) {
            builder = builder.normalize("NFD").replace(/\p{Mn}/gmu, ""); // No I18N
        } else {
            builder = builder.normalize("NFC"); // No I18N
        }

        // whitespace Tokenization
        let originalTokens = builder.trim().split(/\p{White_Space}+/gmu)
        let outputList = [];
        for (let token of originalTokens) {
            if (this.doLowerCase) {
                token = token.toLocaleLowerCase();
            }
            outputList.push(...this.splitOnPunctuation(token));
        }
        return outputList;
    }

    cleanText(text) {
        let sb = "";
        let length = text.length;
        for (let i = 0; i < length; i++) {
            let character = text.charAt(i);
            let charCode = text.codePointAt(i);
            // Control Codes The 65 characters in the ranges U+0000..U+001F and U+007F..U+009F. Also known as control characters.
            // Ref: http://unicode.org/glossary/#control_codes
            if (charCode !== 0 && charCode !== 0xFFFD && this.isNotControlCharacter(character)) {
                /*Check is whitespace*/
                if (this.isWhiteSpace(character)) {
                    sb += " ";
                } else {
                    sb += character;
                }
            }
        }
        return sb;
    }

    splitOnPunctuation(token) {
        let tokens = [];
        let startNewWord = true;
        for (let i = 0; i < token.length; i++) {
            let ch = token.charAt(i);
            if (this.isPunctuation(ch)) {
                tokens.push(ch);
                startNewWord = true;
            } else {
                if (startNewWord) {
                    tokens.push('');
                    startNewWord = false;
                }
                let last = tokens.length - 1;
                tokens[last] = tokens.at(last) + ch;
            }
        }
        return tokens;
    }

    calculateUnicodeLength(input) {
        let length = 0;
        for (let i = 0; i < input.length; i++) {
            // Check if the character is a high surrogate
            if (input.charCodeAt(i) >= 0xD800 && input.charCodeAt(i) <= 0xDBFF) {
                // If it's a high surrogate, increment length by 2 and skip the next character
                length += 2;
                i++; // Skip the low surrogate
            } else {
                // Otherwise, it's a regular character
                length += 1;
            }
        }
        return length;
    }


    tokeniseChineseChars(inputBuilder) {
        let length = inputBuilder.length;
        let outputBuilder = "";
        for (let i = 0; i < length;) {
            // Iterate code points instead of character
            // Since some chinese characters can't be referred as single char
            let character = inputBuilder.codePointAt(i);
            if (this.isChineseCharacter(character)) {
                outputBuilder += ' ';
                outputBuilder += String.fromCodePoint(character);
                outputBuilder += ' ';
            } else {
                outputBuilder += String.fromCharCode(character);
            }
            i += this.calculateUnicodeLength(inputBuilder[i]);
        }
        return outputBuilder;
    }
}

class WordPieceTokeniser {
    static MAX_INPUT_CHARS_PER_WORD = 100;
    static UNKNOWN_TOKEN = "[UNK]"; // No I18N

    constructor(vocab, unkToken) {
        this.vocab = Object.freeze(vocab);
        this.unkToken = unkToken;
    }

    static of(vocab) {
        if (vocab == null) {
            throw new Error("vocab cannot be null"); // No I18N
        }

        // Get unknown ID
        const unkToken = vocab[WordPieceTokeniser.UNKNOWN_TOKEN];

        if (unkToken == null) {
            throw new Error(`UNKNOWN_TOKEN ${WordPieceTokeniser.UNKNOWN_TOKEN} is not found in the vocab`);
        }

        // Initialise the tokeniser
        return new WordPieceTokeniser(vocab, unkToken);
    }

    tokenise(token) {
        if (token == null) {
            throw new Error("text cannot be null"); // No I18N
        }

        // Initialise list to store tokens
        const outputTokens = [];

        const tokenLength = token.length;

        // Insert Unknown token if token length exceeds the limit
        if (tokenLength > WordPieceTokeniser.MAX_INPUT_CHARS_PER_WORD) {
            outputTokens.push(WordPieceTokeniser.UNKNOWN_TOKEN);
            return outputTokens;
        }

        let start = 0;

        // Use StringBuilder to avoid repeated concatenations
        // let subStrBuilder = "##"; // No I18N
        let subStrBuilder = ["##"]; // No I18N

        while (start < tokenLength) {
            let end = tokenLength;

            let found = false;

            while (start < end) {
                let subToken;

                if (start > 0) {
                    subStrBuilder.length = 1
                    subStrBuilder.push(token.substring(start, end))
                    subToken = subStrBuilder.join("")
                } else {
                    subToken = token.substring(start, end);
                }

                // Add sub-token in the list if it presents in vocab
                if (this.vocab.hasOwnProperty(subToken)) {
                    found = true;
                    outputTokens.push(subToken);
                    break;
                }

                end--;
            }

            // If zero token found, return UNKNOWN TOKEN
            if (!found) {
                outputTokens.push(WordPieceTokeniser.UNKNOWN_TOKEN);
                break;
            }

            // Reset start to last sub-token ending
            start = end;
        }

        return outputTokens;
    }

    getID(token) {
        const id = this.vocab[token];
        return id != null ? id : this.unkToken;
    }

    convertTokensToIDs(tokens) {
        const ids = new Array(tokens.length);
        for (const i in tokens) {
            ids[i] = this.getID(tokens[i]);
        }
        return ids;
    }
}


 class BertTokeniser {
    static #MAX_LENGTH = 512;
    static #CLS_TOKEN = "[CLS]";
    static #SEP_TOKEN = "[SEP]";
    static #PAD_TOKEN = "[PAD]";

    #wordPieceTokeniser
    #basicTokeniser
    #padTokenId

    #checkRequiredToken(vocab, reqToken) {
        let token = vocab[reqToken];

        if (token == null) {
            throw new Error(`${reqToken} is not found in the vocab`);
        }
    }

    constructor(vocabList) {
        if (vocabList == null) {
            throw new Error("vocabList cannot be null"); // No I18N
        }

        const vocab = {}
        for (const i in vocabList) {
            vocab[vocabList[i]] = Number.parseInt(i);
        }

        this.#checkRequiredToken(vocab, BertTokeniser.#CLS_TOKEN);
        this.#checkRequiredToken(vocab, BertTokeniser.#SEP_TOKEN);
        this.#checkRequiredToken(vocab, BertTokeniser.#PAD_TOKEN);
        this.#padTokenId = vocab[BertTokeniser.#PAD_TOKEN]

        this.#basicTokeniser = new BasicTokeniser(true, true, true);

        // UNK_TOKEN will check in word piece tokeniser
        this.#wordPieceTokeniser = WordPieceTokeniser.of(vocab);
    }

    // This is used to check pad token index in preprocess
    getPadTokenId() {
        return this.#padTokenId;
    }

    encode(text) {

        if (!text) {
            throw new Error(`"text" must be a non-empty string!`); // No I18N
        }
        let basicTokens = this.#basicTokeniser.Tokenise(text)
        if (basicTokens.length < 1) {
            throw new Error("no valid token found in text!"); // No I18N
        }

        let wordPieceTokens = Array(BertTokeniser.#MAX_LENGTH).fill(BertTokeniser.#PAD_TOKEN);
        wordPieceTokens[0] = BertTokeniser.#CLS_TOKEN;

        let appendTokenIndex = 1;

        for (let i in basicTokens) {
            let basicToken = basicTokens[i];
            let tokens = this.#wordPieceTokeniser.tokenise(basicToken);

            for (let token of tokens) {
                wordPieceTokens[appendTokenIndex] = token;

                // If the got WordPieceTokeniser.#MAX_LENGTH-1 (basicTokens) we stop the loop and assign #SEP_TOKEN at last
                if (appendTokenIndex === BertTokeniser.#MAX_LENGTH - 1) {
                    wordPieceTokens[appendTokenIndex] = BertTokeniser.#SEP_TOKEN;
                    break
                }

                appendTokenIndex++;
            }

            // If the loop going to end assign sep token at end of the tokens index
            if (Number.parseInt(i) === basicTokens.length - 1) {
                wordPieceTokens[appendTokenIndex] = BertTokeniser.#SEP_TOKEN;
            }
        }
        return this.#wordPieceTokeniser.convertTokensToIDs(wordPieceTokens);
    }
}

/**
 * Preprocessor for website categoriser
 * - Grep only alpha-number values from text content
 * - If `strict` will throw if details content (title, meta description, meta keywords) not exists and only have body content have, it's also less than minReqToken (without counting padding token)
 * Example:
 * ```js
 * //
 * // let say `loadVocab()` is a function return list of vocab string
 * // Example: ["a", "an", ...]
 * //
 * const scrapedData = getData();
 * const preprocessor = new Preprocessor(loadVocab());
 *
 * const ids = preprocessor.process(scrapedData);
 * ```
 *
 */
 class Preprocessor {
    #bertTokeniser;
    #strict
    #minReqToken

    /**
     *
     * @param vocab - vocab list
     * @param strict - strictly check min required token for classifier (default: true)
     */
    constructor(vocab, strict=true) {
        this.#bertTokeniser = new BertTokeniser(vocab);
        this.#strict = strict;
        this.#minReqToken = 100;
    }

    #preprocess(...texts) {
        const text = texts.join("\n"); // No I18N
        const preprocessedSentenceLists = text.trim().split("\n")
            .reduce((processedSentences, sentence) => {
                sentence = sentence.replace(/[^a-zA-Z0-9 ]/gm, ' ');
                const words = sentence.split(/\s+/);

                if (words) {
                    processedSentences.push(words.join(" "));
                }

                return processedSentences;
            }, []);

        return preprocessedSentenceLists.join(". ");
    }

    /**
     *
     * @param title
     * @param metaDescription
     * @param metaKeywords
     * @param bodyContent
     * @returns {*}
     */
    process({title, metaDescription, metaKeywords, text /*body content*/}) {
        const detailsString = this.#preprocess(title, metaDescription, metaKeywords);
        let inputString;
        let detailsStringExists = false;

        if(detailsString) {
            inputString = this.#preprocess(detailsString, text);
            detailsStringExists = true;
        } else {
            inputString = this.#preprocess(text);
        }

        let ids = this.#bertTokeniser.encode(inputString);
        let paddingTokenIdx = ids.indexOf(this.#bertTokeniser.getPadTokenId());

        if (this.#strict && // it's on strict mode
            !detailsStringExists && // details string not exists
            paddingTokenIdx!==-1 && // padding token found in ids
            paddingTokenIdx - 1 < this.#minReqToken // Say if pad token stating index is 5, only original token 4 exists
        ) {
            throw Error(`Insufficient data to classify! (Required 100 (if details string not exists) ids, but only have ${paddingTokenIdx.length} valid ids (other than [PAD] token)!)`)
        }

        return ids;
    }
}


